-- The server catalog of identities did not match the app.
--
-- - The app has 13 identities in SeedData. The server had only the first 8. Phase 8
--   added identities 09 to 13 to the app, and no migration added them to the server.
-- - identity_habits had the 34 links of the first catalog. Phase 8 changed the template
--   ids, so 30 of the 34 links pointed at the wrong templates. The app has 93 links.
--
-- The app reads both lists from SeedData, so no screen used the wrong rows. This migration
-- makes the server catalog the same as SeedData. It is safe to run again.
--
-- user_identities.identity_id has no foreign key, so no user row needs a change.

on conflict (id) do update set
  name = excluded.name,
  description = excluded.description,
  icon = excluded.icon,
  hue = excluded.hue;

-- Remove the old links, then insert the links of SeedData.identityHabitMap.
delete from identity_habits;

on conflict do nothing;
